namespace sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Models;

public record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

using sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Models;

namespace sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Models;
using sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Services;

namespace sv_8b92ee0d023a4293bd2bb9980bb09dd5.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 7, 9, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTimeOffset(2026, 7, 3, 10, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", "Memphis, TN", new DateTimeOffset(2026, 7, 4, 6, 30, 0, TimeSpan.Zero)),
                new("In transit to destination", "Memphis, TN", new DateTimeOffset(2026, 7, 5, 14, 0, 0, TimeSpan.Zero)),
            }),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 7, 5, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 7, 1, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at distribution center", "Portland, OR", new DateTimeOffset(2026, 7, 2, 11, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 5, 8, 0, 0, TimeSpan.Zero)),
                new("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 7, 5, 11, 45, 0, TimeSpan.Zero)),
            }),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 12, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", "Chicago, IL", new DateTimeOffset(2026, 7, 6, 8, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Models;

namespace sv_8b92ee0d023a4293bd2bb9980bb09dd5.Client.Services;

public class HttpShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public HttpShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

